import java.io.IOException;
import java.nio.ByteBuffer;
import java.nio.channels.ReadableByteChannel;

public class LspViolationDemo {

    public static class BaseChannelProcessor {
        public void process(ReadableByteChannel channel, ByteBuffer buffer) throws IOException {
            // Contract: Reads data into the buffer; blocks until at least one byte is read.
            channel.read(buffer);
        }
    }

    public static class NonBlockingFaultyProcessor extends BaseChannelProcessor {
        @Override
        public void process(ReadableByteChannel channel, ByteBuffer buffer) throws IOException {
            // LSP Violation: Weakens postcondition and violates expected blocking behavior.
            // If the channel is non-blocking, it might read 0 bytes immediately, 
            // breaking callers who assume 'process' guarantees data consumption.
            int bytesRead = channel.read(buffer);
            if (bytesRead == 0) {
                throw new IllegalStateException("Zero bytes read unexpectedly for synchronous caller");
            }
        }
    }
}
